   218	// percentile returns the nearest-rank percentile of an already-sorted slice.
   219	func percentile(sorted []float64, p float64) float64 {
   220		if len(sorted) == 0 {
   221			return 0
   222		}
   223		rank := int(math.Ceil(p/100*float64(len(sorted)))) - 1
   224		rank = max(rank, 0)
   225		rank = min(rank, len(sorted)-1)
   226		return sorted[rank]
   227	}
